//! JSON output for tooling integration.

use crate::diagnostic::{HelpRenderTarget, render_help};
use crate::linter::LintResult;
use crate::output::shared::{diagnostic_location, rule_docs_path, source_indices};
use serde::Serialize;
use vize_l0::String;

/// JSON output structure for a single file
#[derive(Debug, Serialize)]
pub struct JsonFileResult {
    pub file: String,
    pub messages: Vec<JsonMessage>,
    #[serde(rename = "errorCount")]
    pub error_count: usize,
    #[serde(rename = "warningCount")]
    pub warning_count: usize,
}

/// JSON output structure for a single message
#[derive(Debug, Serialize)]
pub struct JsonMessage {
    #[serde(rename = "ruleId")]
    pub rule_id: &'static str,
    #[serde(rename = "ruleDocsPath")]
    pub rule_docs_path: &'static str,
    pub severity: u8,
    pub message: String,
    pub line: u32,
    pub column: u32,
    #[serde(rename = "endLine")]
    pub end_line: u32,
    #[serde(rename = "endColumn")]
    pub end_column: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub help: Option<String>,
}

/// Format results as JSON
pub(super) fn format_json(results: &[LintResult], sources: &[(String, String)]) -> String {
    let source_indices = source_indices(sources);
    let json_results: Vec<JsonFileResult> = results
        .iter()
        .map(|r| JsonFileResult {
            file: r.filename.clone(),
            messages: r
                .diagnostics
                .iter()
                .map(|d| {
                    let location =
                        diagnostic_location(r.filename.as_str(), d.start, d.end, &source_indices);

                    JsonMessage {
                        rule_id: d.rule_name,
                        rule_docs_path: rule_docs_path(d.rule_name),
                        severity: match d.severity {
                            crate::diagnostic::Severity::Error => 2,
                            crate::diagnostic::Severity::Warning => 1,
                        },
                        // Use formatted message with [vize:RULE] prefix
                        message: d.formatted_message(),
                        line: location.line,
                        column: location.column,
                        end_line: location.end_line,
                        end_column: location.end_column,
                        help: d
                            .help
                            .as_ref()
                            .map(|h| render_help(h, HelpRenderTarget::PlainText)),
                    }
                })
                .collect(),
            error_count: r.error_count,
            warning_count: r.warning_count,
        })
        .collect();

    serde_json::to_string_pretty(&json_results)
        .unwrap_or_else(|_| "[]".to_owned())
        .into()
}

//! Help text formatting and markdown rendering.
//!
//! Provides functions for rendering markdown help text into different
//! output formats: ANSI terminal codes, plain text, or raw markdown passthrough.

use vize_l0::String;
use vize_l0::ToCompactString;

// ANSI escape codes
const ANSI_BOLD: &str = "\x1b[1m";
const ANSI_BOLD_OFF: &str = "\x1b[22m";
const ANSI_UNDERLINE: &str = "\x1b[4m";
const ANSI_UNDERLINE_OFF: &str = "\x1b[24m";
const ANSI_CYAN: &str = "\x1b[36m";
const ANSI_CYAN_OFF: &str = "\x1b[39m";
const ANSI_DIM: &str = "\x1b[2m";
const ANSI_DIM_OFF: &str = "\x1b[22m";

/// Render target for help text conversion at output boundaries.
///
/// Help text is stored as raw markdown in `LintDiagnostic.help`.
/// Use this enum with [`render_help`] to convert at the output boundary.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum HelpRenderTarget {
    /// CLI/TUI: Convert markdown to ANSI escape codes.
    Ansi,
    /// LSP, JSON: Strip markdown syntax for clean text.
    PlainText,
    /// WASM/Playground: Pass through as-is (raw markdown).
    Markdown,
}

/// Render help text (raw markdown) for the given target.
///
/// This function should be called at output boundaries, not when creating diagnostics.
pub fn render_help(markdown: &str, target: HelpRenderTarget) -> String {
    match target {
        HelpRenderTarget::Ansi => render_markdown_to_ansi(markdown),
        HelpRenderTarget::PlainText => strip_markdown(markdown),
        HelpRenderTarget::Markdown => markdown.to_compact_string(),
    }
}

/// Convert markdown text to ANSI-formatted text for TUI display.
///
/// Supports:
/// - `**bold**` / `__bold__` -> ANSI bold
/// - `` `code` `` -> cyan
/// - ```` ``` ```` code blocks -> indented + dim
/// - `# Header` -> bold + underline
pub(crate) fn render_markdown_to_ansi(text: &str) -> String {
    let mut result = String::with_capacity(text.len() + 64);
    let mut in_code_block = false;

    for line in text.lines() {
        let trimmed = line.trim();

        // Handle code fence blocks (check before pushing newline to avoid extra \n)
        if trimmed.starts_with("```") {
            in_code_block = !in_code_block;
            continue;
        }

        if !result.is_empty() {
            result.push('\n');
        }

        // Inside code block: indent + dim
        if in_code_block {
            result.push_str(ANSI_DIM);
            result.push_str("  ");
            result.push_str(line);
            result.push_str(ANSI_DIM_OFF);
            continue;
        }

        // Handle headers: # Header -> bold + underline
        if let Some(header_content) = trimmed.strip_prefix("# ") {
            result.push_str(ANSI_BOLD);
            result.push_str(ANSI_UNDERLINE);
            result.push_str(header_content);
            result.push_str(ANSI_UNDERLINE_OFF);
            result.push_str(ANSI_BOLD_OFF);
            continue;
        }
        if let Some(header_content) = trimmed.strip_prefix("## ") {
            result.push_str(ANSI_BOLD);
            result.push_str(ANSI_UNDERLINE);
            result.push_str(header_content);
            result.push_str(ANSI_UNDERLINE_OFF);
            result.push_str(ANSI_BOLD_OFF);
            continue;
        }
        if let Some(header_content) = trimmed.strip_prefix("### ") {
            result.push_str(ANSI_BOLD);
            result.push_str(header_content);
            result.push_str(ANSI_BOLD_OFF);
            continue;
        }

        // Process inline formatting
        render_inline_markdown(&mut result, line);
    }

    result
}

/// Process inline markdown formatting: **bold**, __bold__, `code`.
fn render_inline_markdown(out: &mut String, line: &str) {
    let bytes = line.as_bytes();
    let len = bytes.len();
    let mut i = 0;

    while let Some(&byte) = bytes.get(i) {
        // Inline code: `code`
        if byte == b'`'
            && let Some(end) = find_closing_backtick(bytes, i + 1)
        {
            out.push_str(ANSI_CYAN);
            out.push_str(line.get(i + 1..end).unwrap_or_default());
            out.push_str(ANSI_CYAN_OFF);
            i = end + 1;
            continue;
        }

        // Bold: **text** or __text__
        if bytes.get(i..i + 2) == Some(b"**".as_slice())
            && let Some(end) = find_closing_double(bytes, i + 2, b'*')
        {
            out.push_str(ANSI_BOLD);
            // Recursively process inline content within bold
            render_inline_markdown(out, line.get(i + 2..end).unwrap_or_default());
            out.push_str(ANSI_BOLD_OFF);
            i = end + 2;
            continue;
        }
        if bytes.get(i..i + 2) == Some(b"__".as_slice())
            && let Some(end) = find_closing_double(bytes, i + 2, b'_')
        {
            out.push_str(ANSI_BOLD);
            render_inline_markdown(out, line.get(i + 2..end).unwrap_or_default());
            out.push_str(ANSI_BOLD_OFF);
            i = end + 2;
            continue;
        }

        // Copy plain text up to the next delimiter byte. Delimiters are ASCII,
        // so both ends stay on char boundaries and non-ASCII text survives.
        let next = bytes
            .get(i + 1..)
            .and_then(|rest| rest.iter().position(|b| matches!(b, b'`' | b'*' | b'_')))
            .map_or(len, |offset| i + 1 + offset);
        out.push_str(line.get(i..next).unwrap_or_default());
        i = next;
    }
}

/// Find closing backtick for inline code.
fn find_closing_backtick(bytes: &[u8], start: usize) -> Option<usize> {
    let offset = bytes.get(start..)?.iter().position(|&b| b == b'`')?;
    Some(start + offset)
}

/// Find closing double delimiter (** or __).
fn find_closing_double(bytes: &[u8], start: usize, ch: u8) -> Option<usize> {
    let mut i = start;
    while i + 1 < bytes.len() {
        if bytes.get(i..i + 2) == Some([ch, ch].as_slice()) {
            return Some(i);
        }
        i += 1;
    }
    None
}

/// Strip all markdown formatting from text, producing clean plain text.
pub(crate) fn strip_markdown(text: &str) -> String {
    let mut result = String::with_capacity(text.len());
    let mut in_code_block = false;

    for line in text.lines() {
        let trimmed = line.trim();

        // Handle code fence blocks
        if trimmed.starts_with("```") {
            in_code_block = !in_code_block;
            continue;
        }

        // Inside code block: keep content with indent
        if in_code_block {
            if !result.is_empty() {
                result.push('\n');
            }
            result.push_str("  ");
            result.push_str(trimmed);
            continue;
        }

        // Skip empty lines (but preserve paragraph breaks)
        if trimmed.is_empty() {
            if !result.is_empty() && !result.ends_with('\n') {
                result.push('\n');
            }
            continue;
        }

        if !result.is_empty() && !result.ends_with('\n') {
            result.push('\n');
        }

        // Strip markdown headers
        let content = trimmed
            .strip_prefix("### ")
            .or_else(|| trimmed.strip_prefix("## "))
            .or_else(|| trimmed.strip_prefix("# "))
            .unwrap_or(trimmed);

        // Strip bold/italic markers and inline code backticks
        let content = content.replace("**", "").replace("__", "").replace('`', "");
        result.push_str(content.trim());
    }

    // Trim trailing whitespace/newlines
    let trimmed = result.trim_end();
    trimmed.to_compact_string()
}

//! Result retention and summary aggregation for parallel lint runs.

use super::cross_file::CliLintFileResult;
use std::cmp::Ordering;
use vize_patina::{LintDiagnostic, OutputFormat, Severity};

pub(super) struct LintRunAccumulator {
    error_count: usize,
    warning_count: usize,
    results: Option<Vec<CliLintFileResult>>,
}

impl LintRunAccumulator {
    pub(super) fn new(retain_file_results: bool) -> Self {
        Self {
            error_count: 0,
            warning_count: 0,
            results: retain_file_results.then(Vec::new),
        }
    }

    pub(super) fn push(mut self, file_result: CliLintFileResult) -> Self {
        self.error_count += file_result.3.error_count;
        self.warning_count += file_result.3.warning_count;
        if let Some(results) = self.results.as_mut() {
            results.push(file_result);
        }
        self
    }

    pub(super) fn merge(mut self, other: Self) -> Self {
        self.error_count += other.error_count;
        self.warning_count += other.warning_count;
        // Accumulators share one retention mode; should they ever differ, keep
        // whatever either side retained.
        match (&mut self.results, other.results) {
            (Some(results), Some(other_results)) => results.extend(other_results),
            (slot @ None, Some(other_results)) => *slot = Some(other_results),
            (_, None) => {}
        }
        self
    }

    pub(super) fn into_parts(self) -> (Vec<CliLintFileResult>, Option<(usize, usize)>) {
        let quiet_totals = self
            .results
            .is_none()
            .then_some((self.error_count, self.warning_count));
        (self.results.unwrap_or_default(), quiet_totals)
    }
}

pub(super) fn totals(
    quiet_totals: Option<(usize, usize)>,
    results: &[CliLintFileResult],
) -> (usize, usize) {
    quiet_totals.unwrap_or_else(|| {
        results
            .iter()
            .fold((0, 0), |(errors, warnings), (_, _, _, result)| {
                (errors + result.error_count, warnings + result.warning_count)
            })
    })
}

pub(super) fn sorted_totals(
    quiet_totals: Option<(usize, usize)>,
    results: &mut [CliLintFileResult],
) -> (usize, usize) {
    sort_details_for_output(results);
    totals(quiet_totals, results)
}

pub(super) fn sort_details_for_output(results: &mut [CliLintFileResult]) {
    results.sort_by(compare_file_result);
    for (_, _, _, result) in results {
        for diagnostic in &mut result.diagnostics {
            diagnostic.labels.sort_by(|left, right| {
                left.start
                    .cmp(&right.start)
                    .then_with(|| left.end.cmp(&right.end))
                    .then_with(|| left.message.cmp(&right.message))
            });
        }
        result.diagnostics.sort_by(compare_diagnostic);
    }
}

fn compare_file_result(left: &CliLintFileResult, right: &CliLintFileResult) -> Ordering {
    left.1.cmp(&right.1).then_with(|| left.0.cmp(&right.0))
}

fn compare_diagnostic(left: &LintDiagnostic, right: &LintDiagnostic) -> Ordering {
    left.start
        .cmp(&right.start)
        .then_with(|| left.end.cmp(&right.end))
        .then_with(|| severity_rank(left.severity).cmp(&severity_rank(right.severity)))
        .then_with(|| left.rule_name.cmp(right.rule_name))
        .then_with(|| left.message.cmp(&right.message))
        .then_with(|| left.help.cmp(&right.help))
        .then_with(|| compare_label_sequences(left, right))
}

fn compare_label_sequences(left: &LintDiagnostic, right: &LintDiagnostic) -> Ordering {
    left.labels
        .iter()
        .map(|label| (label.start, label.end, label.message.as_str()))
        .cmp(
            right
                .labels
                .iter()
                .map(|label| (label.start, label.end, label.message.as_str())),
        )
}

fn severity_rank(severity: Severity) -> u8 {
    match severity {
        Severity::Error => 0,
        Severity::Warning => 1,
    }
}

#[inline]
pub(super) fn should_retain_file_results(render_details: bool, cross_file_enabled: bool) -> bool {
    render_details || cross_file_enabled
}

#[inline]
pub(super) fn should_render_details(format: OutputFormat, quiet: bool) -> bool {
    format.renders_details_when_quiet() || !quiet
}

